const d = $input.first().json;
const prompt = 'Tu es un expert RH. Analyse le CV et la lettre ci-joints.\n\n'
  + '=== FICHE DE POSTE ===\n'
  + 'Titre: ' + d.titre_poste + '\n'
  + 'Missions: ' + d.description_poste + '\n'
  + 'Profil souhaitée: ' + d.profil_souhaite + '\n'
  + 'Competences: ' + d.competences_requises + '\n'
  + 'Experience: ' + (d.annees_experience || 'Non specifie') + '\n'
  + 'Langues: ' + (d.langues_requises || 'Non specifie') + '\n'
  + 'Contrat: ' + d.type_contrat + '\n'
  + 'Lieu: ' + d.localisation + '\n'
  + (d.exigences_ia ? '\n=== EXIGENCES PRIORITAIRES ===\n' + d.exigences_ia + '\n' : '')
  + '\nRepondre UNIQUEMENT en JSON valide:\n'
  + '{"score":7,"competences_detectees":["X"],"competences_manquantes":["Y"],"experience_annees":3,"niveau_education":"Licence","adequation_poste":"Bon profil.","points_forts":"Experience pertinente.","points_faibles":"Peu de management.","resume_analyse":"Candidat interessant.","recommandation":"QUALIFIE"}\n'
  + 'Score>=7=QUALIFIE, 4-6=A_REVOIR, <4=NON_SELECTIONNE\n'
  + 'IMPORTANT: Reponds UNIQUEMENT avec le JSON brut. Pas de bloc markdown, pas de backticks, pas de texte avant ou apres.';
const content = [];
if (d.cv_base64) {
  if ((d.cv_mimetype||'').includes('pdf'))
    content.push({type:'document',source:{type:'base64',media_type:'application/pdf',data:d.cv_base64}});
  else
    content.push({type:'text',text:'=== CV ===\n'+Buffer.from(d.cv_base64,'base64').toString('utf-8')});
}
if (d.lettre_base64) {
  if ((d.lettre_mimetype||'').includes('pdf'))
    content.push({type:'document',source:{type:'base64',media_type:'application/pdf',data:d.lettre_base64}});
  else
    content.push({type:'text',text:'=== Lettre ===\n'+Buffer.from(d.lettre_base64,'base64').toString('utf-8')});
}
content.push({type:'text',text:prompt});
const isEn = (d.company || 'solumada') === 'optimum';
if (isEn) {
  prompt += '\n\nIMPORTANT: All text fields in your JSON response MUST be in English (resume_analyse, adequation_poste, points_forts, points_faibles, competences_detectees, competences_manquantes).';
}
return [{json:{...d, requestBody:{model:'claude-sonnet-4-6',max_tokens:2048,messages:[{role:'user',content}]}}}];

const item = $input.first().json;
const raw = (item.content && item.content[0] && item.content[0].text) ? item.content[0].text : '';
// Supprimer le bloc markdown ```json ... ``` si présent
const match = raw.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
const jsonStr = match ? match[1].trim() : raw.trim();
let analyse;
try {
  analyse = JSON.parse(jsonStr);
} catch(e) {
  throw new Error('Impossible de parser la réponse Claude : ' + e.message + ' — Réponse brute : ' + raw.slice(0, 200));
}
return [{ json: { ...item, analyse } }];

const email = $('05 - Parse Claude Response').item.json.candidat_email.toLowerCase();
const bookings = $input.first().json.data.bookings || [];
const rdv = bookings.some(b =>
  (b.status === 'ACCEPTED' || b.status === 'PENDING') &&
  (b.attendees || []).some(a => a.email?.toLowerCase() === email)
);
return [{ json: { rdv_trouve: rdv } }];

const email = $('05 - Parse Claude Response').item.json.candidat_email.toLowerCase();
const bookings = $input.first().json.data.bookings || [];
const rdv = bookings.some(b =>
