);
return [{ json: { rdv_trouve: rdv } }];

const parsed  = $('05 - Parse Claude Response').item.json;
const email   = parsed.candidat_email.toLowerCase();
const url     = parsed.callback_url + '/' + parsed.candidature_id + '/rdv-confirme';
const secret  = parsed.callback_secret;

let bookings = [];
try {
  bookings = $('16 - Check Cal.com 2').item.json?.data?.bookings || [];
} catch(e) {}
if (!bookings.length) {
  try {
    bookings = $('11 - Check Cal.com').item.json?.data?.bookings || [];
  } catch(e) {}
}

const booking = bookings.find(b =>
  (b.attendees || []).some(a => a.email?.toLowerCase() === email)
);

let date = null, heure = '', lieu = '';
if (booking) {
  const start = new Date(booking.startTime || booking.start);
  date  = start.toISOString();
  heure = start.toISOString().slice(11, 16);
  lieu  = booking.location || '';
}

return [{ json: { url, secret, date, heure, lieu } }];

